{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "The closest structural analogue, CLR457, which shares the triazine-morpholine and CF3/amino-heteroaryl motif, showed a brain/plasma AUC ratio of only 0.07, indicating minimal CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "A CF3-containing morpholine amide analogue showed a brain unbound/plasma unbound ratio of 0.08, consistent with poor brain penetration in a scaffold related to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "A related amino-pyridine/morpholine-type compound produced minimal total brain exposure (AUC0-8 = 104 ng·h/g) after oral dosing in rats, supporting poor CNS access for this chemical class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A lower-similarity morpholine-pyridine radiotracer showed good brain uptake by PET (SUV 2.8), demonstrating that morpholine-containing heteroaromatics are not universally non-penetrant.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C05"],
      "claim": "GNE-7915, a CF3/morpholine-containing compound, was brain-penetrant with a rat CSF/plasma unbound ratio of 0.6, providing a lower-similarity counterexample to the poor-penetration pattern.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The highest-similarity direct evidence (CLR457, brain/plasma AUC 0.07) and multiple related CF3/morpholine analogues with very low brain exposure indicate inadequate CNS access. Although some lower-similarity morpholine heteroaromatics are brain-penetrant, the more transferable experimental data support a fail prediction for this bis-morpholino triazine.",
  "evidence_gaps": [
    "No direct brain/plasma, CSF, or unbound brain measurement exists for the exact query molecule.",
    "Transporter-mediated efflux status of the query is unknown, though poor ratios in analogues suggest possible efflux liability.",
    "The brain-penetrant counterexamples are structurally more distant, so their relevance to the bis-morpholino triazine core is limited."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

